def percentile(values, q):
    import math
    if not 0<=q<=1: raise ValueError('q')
    if not values: return None
    v=sorted(values); x=(len(v)-1)*q; lo=math.floor(x); hi=math.ceil(x)
    return v[lo]+(v[hi]-v[lo])*(x-lo)

